        newPosition = beforeCard.position + 0.5;
      } else if (afterId) {
        // Before some card
        const { rows: [afterCard] } = await tx.query('SELECT position FROM cards WHERE id = $1', [afterId]);
        newPosition = afterCard.position - 0.5;
      } else {
