    const res = await fetch(`${API_BASE}/cards`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ columnId, text })
    });
    if (!res.ok) throw new Error('Failed to create card');
  } catch (err) {
    console.error(err);
    await fetchBoard();
  }
