    // 1. Remove everywhere else
    board.forEach(col => {
      col.cards = col.cards.filter(c => c.id !== data.id);
    });

    // 2. Add to new column
    const col = board.find(c => c.id === data.column_id);
    if (col) {
      col.cards.push(data);
      col.cards.sort((a, b) => a.position - b.position);
    }
  }
  renderBoard();
};

eventSource.onerror = (err) => {
  console.error('SSE error:', err);
};

// Start the app
